using System;
using Unity.Cinemachine;
using UnityEngine;

[Serializable]
public class FeedbackPacket
{
    public float CameraShakeFrequency;
    public float CameraShakeAmplitude;
    public float CameraShakeDuration;

    public bool IsGamepad;
    public float GamepadMotorLowFrequency;
    public float GamepadMotorHighFrequency;
    public float GamepadMotorFeedbackDuration;

}


public class GameCamera : MonoBehaviour
{
    public static GameCamera Instance;
    CinemachineCamera cam;
    CinemachineBasicMultiChannelPerlin cameraShaker;

    private void Awake()
    {
        if(Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }

        DontDestroyOnLoad(gameObject);        

        Instance = this;

    }

    private void Start()
    {
        cam = GetComponentInChildren<CinemachineCamera>();
    }

    void LinkTrackingTarget(Transform target)
    {
        cam.Target.TrackingTarget = target;
    }


    public static void Track(Transform target)
    {
        Instance.LinkTrackingTarget(target);
    }
}

using System;
using System.Collections;
using Unity.Jobs.LowLevel.Unsafe;
using Unity.VisualScripting;
using UnityEngine;

public class GameManager : MonoBehaviour
{

    public static GameManager Instance;

    public GameObject Player_prefab;
    public GameObject Enemy_prefab;

    [SerializeField] bool lock_cursor = false;

    [SerializeField] bool start_scene_auto = false;
    [SerializeField] string scene_name = "";

    static PlayerSaveData testSave() => new PlayerSaveData { WorldPosition = Vector3.zero, WorldRotation = Quaternion.identity };
    public Action OnPlayerSpawned;
    public Action OnPlayerDied;

    private void Awake()
    {
        Screen.SetResolution(1920, 1080, FullScreenMode.FullScreenWindow, new RefreshRate { numerator = 144, denominator = 1 });

        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }

        DontDestroyOnLoad(gameObject);
        Instance = this;

    }

    private void Start()
    {
        if (start_scene_auto && !string.IsNullOrEmpty(scene_name))
        {
            GameSceneLoader.LoadSceneCustom(scene_name);
        }
    }

    public void PlayerDied()
    {
        StartCoroutine(nameof(PlayerDeathDelayMenu));
    }

    IEnumerator PlayerDeathDelayMenu()
    {
        yield return new WaitForSeconds(2);
        OnPlayerDied?.Invoke();
        yield return null;
    }

    public void HideCursor()
    {
        Cursor.lockState = CursorLockMode.Locked;
        Cursor.visible = false;
    }

    public void ShowCursor(bool isFree = false)
    {
        Cursor.lockState = isFree ? CursorLockMode.None : CursorLockMode.Confined;
        Cursor.visible = true;
    }

    PlayerSaveData runtimeData;

    public void LoadGame()
    {
        runtimeData = testSave();
    }

    public void SaveGame()
    {

    }


    public void SpawnEnemy(Transform spawnTransform)
    {
        var go = Instantiate(Enemy_prefab);
        go.transform.position = spawnTransform.position;
        go.transform.rotation = spawnTransform.rotation;

        var enemy = go.GetComponent<EnemyAgent>();
    }
    public GameObject SpawnEnemy(Vector3 spawnPos, Quaternion spawnRot)
    {
        var go = Instantiate(Enemy_prefab);
        go.transform.position = spawnPos;
        go.transform.rotation = spawnRot;

        return go;

    }
    internal void SpawnPlayer(Transform spawnTransform)
    {
        var go = Instantiate(Player_prefab);
        go.transform.position = spawnTransform.position;
        go.transform.rotation = spawnTransform.rotation;

        player = go.GetComponent<Player>();
        player.Initilize();

        OnPlayerSpawned?.Invoke();
    }
    internal void SpawnPlayer()
    {
        var go = Instantiate(Player_prefab);
        go.transform.position = runtimeData.WorldPosition;
        go.transform.rotation = runtimeData.WorldRotation;

        player = go.GetComponent<Player>();
        player.Initilize();

        OnPlayerSpawned?.Invoke();
    }




    internal void PrepareGameCamera()
    {
        var track = player.transform.GetChild(0);
        GameCamera.Track(track);

        if(lock_cursor is true)
            HideCursor();
    }

    bool isPaused = false;

    internal static void TryPause()
    {
        Instance.HandlePause();
    }
    private void Update()
    {
        if(delayPauseTimer > 0)
        {
            delayPauseTimer -= Time.deltaTime; 
        }

        if(delayPauseTimer < 0)
        {
            delayPauseTimer = 0;
        }


    }


    float delayPauseTime = 0.3f;
    float delayPauseTimer = 0.0f;

    private void HandlePause()
    {
        if (delayPauseTimer > 0.0f) return;

        delayPauseTimer = delayPauseTime;
        isPaused = !isPaused;

        OnPause?.Invoke(isPaused);
    }
    void HandleUnpause()
    {
        delayPauseTimer = delayPauseTime;
        isPaused = false;
        OnPause?.Invoke(isPaused);
    }

    internal static void Unpause()
    {
        Instance.HandleUnpause();
    }

    Player player;
    public Player Player { get { return player; } }

    public Action<bool> OnPause;
}

using Unity.Cinemachine;
using UnityEngine;
using UnityEngine.InputSystem;

public class Haptics : MonoBehaviour
{
    public static Haptics Instance;

    CinemachineBasicMultiChannelPerlin cameraShaker;


    float gamepadLowFrequency;
    float gamepadHighFrequency;

    float cameraShakeTimer;
    float gamepadVibrateTimer;

    private void Awake()
    {
        if(Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }

        Instance = this;
    }

    private void Start()
    {
        cameraShaker = GetComponentInChildren<CinemachineBasicMultiChannelPerlin>();

        if (Gamepad.current != null)
        {
            Gamepad.current.SetMotorSpeeds(0.5f, 1.0f);
            Invoke(nameof(StopRumble), 1.0f);
        }
    }

    private void StopRumble()
    {
        if (Gamepad.current != null)
            Gamepad.current.SetMotorSpeeds(0, 0);
    }

    private void Update()
    {
        if (cameraShakeTimer > 0)
        {
            cameraShakeTimer -= Time.deltaTime;
            if (cameraShakeTimer < 0)
            {
                cameraShakeTimer = 0;

                cameraShaker.AmplitudeGain = 0.0f;
                cameraShaker.FrequencyGain = 0.0f;
            }
        }


        if(gamepadVibrateTimer > 0)
        {
            gamepadVibrateTimer -= Time.deltaTime;

            if(gamepadVibrateTimer <= 0)
            {
                gamepadVibrateTimer = 0;

                gamepadLowFrequency = 0;
                gamepadHighFrequency = 0;
            }
        }

        if(Gamepad.current != null)
            Gamepad.current.SetMotorSpeeds(gamepadLowFrequency, gamepadHighFrequency);
    }

    void StartShakingCamera(float amplitude, float frequency, float duration)
    {
        cameraShaker.AmplitudeGain = amplitude;
        cameraShaker.FrequencyGain = frequency;

        cameraShakeTimer = duration;
    }
    void StartVibratingController(float lowFreq, float highFreq, float duration)
    {
        gamepadHighFrequency = highFreq;
        gamepadLowFrequency = lowFreq;

        gamepadVibrateTimer = duration;
    }

    public static void ApplyFeedback(FeedbackPacket pkt)
    {
        if (pkt.IsGamepad)
            Instance.StartVibratingController(pkt.GamepadMotorLowFrequency, pkt.GamepadMotorHighFrequency, pkt.GamepadMotorFeedbackDuration);

        Instance.StartShakingCamera(pkt.CameraShakeAmplitude, pkt.CameraShakeFrequency, pkt.CameraShakeDuration);

    }




}

using UnityEngine;

public class LaserPointer : MonoBehaviour
{
    Transform p0;
    Transform p1;

    LineRenderer lr;


    private void Start()
    {
        p0 = transform.GetChild(0);
        p1 = transform.GetChild(1);


        lr = GetComponent<LineRenderer>();

    }

    private void Update()
    {
        if(Physics.Raycast(transform.position, transform.forward, out var hit, 100))
        {
            p1.position = hit.point;
        }
        else
        {
            p1.position = p0.position + (p0.forward * 100);
        }

        lr.SetPositions(new Vector3[2] { p0.position, p1.position });
    }
}

