    static string SCENE_001 = "SCENE_001";

    public static void LoadMainMenu()
    {
        SceneManager.LoadScene(MAIN_MENU);
    }

    public static void LoadSceneOne()
    {
        SceneManager.LoadScene(SCENE_001);
