using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using UnityEngine.AI;

public enum SpawnVolumeType
{
    Sphere,
    Cuboid
}

public class AmbientSpawner : MonoBehaviour
{
    [Header("Editor Only!")]
    [SerializeField] bool is_simulationMode = false;
    [SerializeField] GameObject[] simulationPrefabs;

    [Header("Spawn Settings")]
    public int maxZombies = 10;
    public SpawnVolumeType volumeType = SpawnVolumeType.Sphere;

    [Header("Sphere Settings")]
    public float spawnRadius = 20f;

    [Header("Cuboid Settings")]
    public Vector3 spawnExtents = new Vector3(20f, 5f, 20f); // half-size in each axis

    [Header("Clustering Settings")]
    public bool enableClustering = false;
    public int clusters = 3;
    public float clusterRadius = 5f;

    private List<GameObject> zombies = new List<GameObject>();

    private void Start()
    {
        SpawnAllZombies();
    }

    private void SpawnAllZombies()
    {
        if (enableClustering && clusters > 0)
        {
            SpawnClustered();
        }
        else
        {
            for (int i = 0; i < maxZombies; i++)
            {
                TrySpawnZombie(GetRandomPointInVolume());
            }
        }
    }

    private void SpawnClustered()
    {
        int zombiesPerCluster = Mathf.CeilToInt((float)maxZombies / clusters);

        for (int c = 0; c < clusters; c++)
        {
            // Pick a cluster center inside the volume
            Vector3 clusterCenter = GetRandomPointInVolume();

            for (int i = 0; i < zombiesPerCluster; i++)
            {
                Vector3 offset = Random.insideUnitSphere * clusterRadius;
                offset.y = 0;
                TrySpawnZombie(clusterCenter + offset);
            }
        }
    }

    private void TrySpawnZombie(Vector3 pos)
    {
        if (NavMesh.SamplePosition(pos, out var hit, 5f, NavMesh.AllAreas))
        {

            GameObject zombie = null;
            if (is_simulationMode)
            {
                // determine zombie by probabillity.
                // right now there is only the shambler types as prefabs.. but should soon be 
                // phased into their own prefabs.


                zombie = Instantiate(simulationPrefabs[0]);

                zombie.transform.position = hit.position;

                Vector2 offset = Random.insideUnitCircle;
                Vector3 targetPosition = hit.position + new Vector3(offset.x, 0, offset.y);
                var dir = targetPosition - hit.position;

                if (dir.sqrMagnitude < 0.0001f)
                    dir = Vector3.forward;

                Quaternion lookDir = Quaternion.LookRotation(dir);

                zombie.transform.rotation = lookDir;
            }   
            else
            {
               zombie =  GameManager.Instance.SpawnEnemy(hit.position, Quaternion.identity);
            }
            zombies.Add(zombie);

            //var resolver = zombie.GetComponent<EnemyAgent>();
            //if (resolver != null)
            //{
            //    resolver.SetPassive(true);
            //}
        }
    }

    private Vector3 GetRandomPointInVolume()
    {
        switch (volumeType)
        {
            case SpawnVolumeType.Cuboid:
                Vector3 randomOffset = new Vector3(
                    Random.Range(-spawnExtents.x, spawnExtents.x),
                    Random.Range(-spawnExtents.y, spawnExtents.y),
                    Random.Range(-spawnExtents.z, spawnExtents.z)
                );
                return transform.position + randomOffset;

            case SpawnVolumeType.Sphere:
            default:
                Vector3 randomPos = transform.position + Random.insideUnitSphere * spawnRadius;
                randomPos.y = transform.position.y; // flatten to ground
                return randomPos;
        }
    }

    private void OnDrawGizmos()
    {
        Gizmos.color = Color.yellow;

        if (volumeType == SpawnVolumeType.Sphere)
        {
            Gizmos.DrawWireSphere(transform.position, spawnRadius);
        }
        else if (volumeType == SpawnVolumeType.Cuboid)
        {
            Gizmos.DrawWireCube(transform.position, spawnExtents * 2f);
        }

        if (enableClustering)
        {
            Gizmos.color = Color.cyan;
            for (int i = 0; i < clusters; i++)
            {
                Vector3 clusterCenter = Application.isPlaying ? GetRandomPointInVolume() : transform.position;
                Gizmos.DrawWireSphere(clusterCenter, clusterRadius);
            }
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

[CreateAssetMenu(menuName = "GOAP/Eat")]
public class EatAction : GOAPAction
{
    public float eatDuration = 2.0f;
    float timer;
    Transform food;

    private void OnEnable()
    {
        actionName = "Eat";
        preconditions = new List<string> { GOAPKeys.AtFood };
        effects = new List<string> { GOAPKeys.Fed };
        duration = eatDuration;
    }

    public override bool CheckPreconditions(Dictionary<string, object> worldState)
    {
        return worldState.TryGetValue(GOAPKeys.AtFood, out var o) && o is bool b && b;
    }

    public override bool StartAction(Dictionary<string, object> worldState)
    {
        timer = eatDuration;
        food = null;

        if (worldState.TryGetValue(GOAPKeys.FoodTarget, out var o) && o is Transform t)
        {
            food = t;
            SetTarget(food); // so rotation faces it
        }

        return food != null;
    }

    public override bool PerformAction(float deltaTime, Dictionary<string, object> worldState)
    {
        timer -= deltaTime;
        if (timer <= 0f)
        {
            worldState[GOAPKeys.Fed] = true;
            worldState[GOAPKeys.HasFoodTarget] = false;
            worldState[GOAPKeys.AtFood] = false;
            worldState[GOAPKeys.FoodTarget] = null;
            worldState[GOAPKeys.KnownFood] = null;

            if (food != null)
                GameObject.Destroy(food.gameObject);

            return true; // finished
        }
        return false;
    }

    public override bool RequiresInRange() => true;
}

using UnityEngine;
using UnityEngine.AI;

[RequireComponent(typeof(EnemyAgent))]
public class Enemy : SoundWaveListener
{
    [Header("Stats")]
    [SerializeField] float maxHP = 100f;
    [SerializeField] int damagePotential = 40;

    [Header("Runtime")]
    [SerializeField] bool isPlayerHoveringMe = false;

    // cached components
    EnemyAgent agent;
    NavMeshAgent navAgent;
    Collider mainCollider;
    Animator animator;
    float hp;
    bool isDead = false;

    void Awake()
    {
        hp = maxHP;
        agent = GetComponent<EnemyAgent>();
        // prefer NavMeshAgent on same object, otherwise find in children
        navAgent = GetComponent<NavMeshAgent>();
        if (navAgent == null) navAgent = GetComponentInChildren<NavMeshAgent>();
        mainCollider = GetComponent<Collider>();
        animator = GetComponentInChildren<Animator>();
    }

    void Start()
    {
    }

    protected override void ReactToSoundHeard(Vector3 sourcePos, string tag)
    {
        if (isDead) return;
        // Alert the behavior runner (EnemyAgent) to investigate the sound/player
        agent?.AlertToSound(sourcePos);
    }

    void Update()
    {
        if (isDead) return;

        // layer highlight for hover
        SetLayer(isPlayerHoveringMe ? "Enemy - Outline" : "Enemy");

        // death check
        if (hp <= 0f)
            Die();
    }

    void LateUpdate()
    {
        // reset hover each frame; external systems should call SetIsPlayerLookingAtMe(true)
        isPlayerHoveringMe = false;
    }

    public void DealDamage(float value)
    {
        if (isDead) return;
        hp -= value;
        if (hp <= 0f) Die();
    }

    public int GetDamage() => damagePotential;

    public void SetIsPlayerLookingAtMe(bool v)
    {
        isPlayerHoveringMe = v;
    }

    void Die()
    {
        if (isDead) return;
        isDead = true;

        if (animator != null)
        {
            animator.SetTrigger("Death");
        }

        if (mainCollider != null)
            mainCollider.enabled = false;

        if (agent != null)
            agent.enabled = false;

        if (navAgent != null)
            navAgent.enabled = false;

        SoundWaveManager.RemoveListener(this);

        // Optional: Destroy after some delay or leave corpse
        // Destroy(gameObject, 10f);
    }

    public void SetLayer(string layerName)
    {
        int layerIndex = LayerMask.NameToLayer(layerName);
        if (layerIndex == -1)
        {
            Debug.LogWarning($"Layer \"{layerName}\" does not exist!");
            return;
        }

        gameObject.layer = layerIndex;

        var skinnedMeshes = GetComponentsInChildren<SkinnedMeshRenderer>(true);
        foreach (var mesh in skinnedMeshes)
            mesh.gameObject.layer = layerIndex;

        var renderers = GetComponentsInChildren<Renderer>(true);
        foreach (var r in renderers)
            r.gameObject.layer = layerIndex;
    }


}

using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.AI;

[RequireComponent(typeof(NavMeshAgent))]
public class EnemyAgent : MonoBehaviour
{
    [Header("GOAP Actions (ScriptableObjects)")]
    public List<GOAPAction> availableActions = new List<GOAPAction>();

    [Header("Goal")]
    public List<string> primaryGoal = new List<string> { "Fed" };

    [Header("Perception")]
    public LayerMask foodMask;
    public float visionRange = 15f;

    [Header("Rotation")]
    [SerializeField] float minTurnSpeed = 3f;
    [SerializeField] float maxTurnSpeed = 12f;
    [SerializeField] float attackTurnSpeed = 8f;

    [Header("Debug")]
    public bool verboseLogs = false;

    NavMeshAgent agent;
    Dictionary<string, object> worldState = new Dictionary<string, object>();

    List<GOAPAction> currentPlan = null;
    int planIndex = 0;
    GOAPAction currentAction = null;

    void Awake()
    {
        agent = GetComponent<NavMeshAgent>();
        agent.updateRotation = false;
        agent.updatePosition = false; 
    }
    void OnDrawGizmosSelected()
    {
        if (currentAction != null)
        {
            currentAction.OnDrawGizmosSelected();

#if UNITY_EDITOR       
            Vector3 pos = transform.position + Vector3.up * 2.0f;
            UnityEditor.Handles.color = Color.white;
            UnityEditor.Handles.Label(pos, $"Action: {currentAction.actionName}");
#endif
        }
    }
    void OnDrawGizmos()
    {
        if (currentAction == null) return;

    }


    void Start()
    {

        var instancedActions = new List<GOAPAction>();
        foreach (var a in availableActions)
        {
            var clone = Instantiate(a);   
            clone.AwakeAction(this.gameObject);
            instancedActions.Add(clone);
        }
        availableActions = instancedActions;

        worldState[GOAPKeys.Fed] = false;
        worldState[GOAPKeys.HasFoodTarget] = false;
        worldState[GOAPKeys.AtFood] = false;
        worldState[GOAPKeys.FoodTarget] = null;

        foreach (var a in availableActions) a.AwakeAction(this.gameObject);
        StartCoroutine(PlannerLoop());
    }

    IEnumerator PlannerLoop()
    {
        while (true)
        {
            yield return ReplanIfNeeded();
            yield return new WaitForSecondsRealtime(0.25f);
        }
    }

    IEnumerator ReplanIfNeeded()
    {
        if (currentPlan == null || !GoalSatisfied())
        {
            UpdateSenses();

            var plan = GOAPPlanner.Plan(this.gameObject, availableActions, worldState, primaryGoal, maxDepth: 6);
            if (plan != null && plan.Count > 0)
            {
                currentPlan = plan;
                planIndex = 0;
                StartNextAction();
            }
            else
            {
                var wander = availableActions.Find(a => a is WanderAction);
                if (wander != null)
                {
                    currentPlan = new List<GOAPAction> { wander };
                    planIndex = 0;
                    StartNextAction();
                }
            }
        }
        yield return null;
    }

    void Update()
    {
        UpdateRotation();

        if (currentAction != null)
        {
            bool finished = currentAction.PerformAction(Time.deltaTime, worldState);
            if (finished)
            {
                planIndex++;
                if (planIndex >= currentPlan.Count)
                {
                    currentPlan = null;
                    currentAction = null;
                }
                else
                {
                    StartNextAction();
                }
            }
        }
    }

    void StartNextAction()
    {
        if (currentPlan == null || planIndex >= currentPlan.Count) return;
        currentAction = currentPlan[planIndex];
        currentAction.AwakeAction(this.gameObject);

        if (worldState.TryGetValue(GOAPKeys.FoodTarget, out var o) && o is Transform t)
            currentAction.SetTarget(t);

        if (!currentAction.StartAction(worldState))
        {
            currentPlan = null;
            currentAction = null;
        }
    }

    bool GoalSatisfied()
    {
        foreach (var g in primaryGoal)
        {
            if (!worldState.ContainsKey(g) || !(worldState[g] is bool b && b))
                return false;
        }
        return true;
    }

    void UpdateSenses()
    {
        Collider[] hits = Physics.OverlapSphere(transform.position, visionRange, foodMask);
        if (hits.Length > 0)
        {
            float best = float.MaxValue;
            Transform bestT = null;
            foreach (var h in hits)
            {
                var d = (h.transform.position - transform.position).sqrMagnitude;
                if (d < best) { best = d; bestT = h.transform; }
            }
            if (bestT != null)
            {
                worldState[GOAPKeys.KnownFood] = bestT;
                worldState[GOAPKeys.HasFoodTarget] = true;
                worldState[GOAPKeys.FoodTarget] = bestT;
            }
        }
    }

    void UpdateRotation()
    {
        if (agent == null) return;

        Vector3 forwardSource = Vector3.zero;

        if (currentAction != null && currentAction.target != null)
            forwardSource = currentAction.target.position - transform.position;

        if (forwardSource.sqrMagnitude < 0.0001f)
            forwardSource = agent.desiredVelocity;

        if (forwardSource.sqrMagnitude < 0.0001f && agent.hasPath)
            forwardSource = agent.steeringTarget - transform.position;

        forwardSource.y = 0f;

        if (forwardSource.sqrMagnitude > 0.001f)
        {
            float velocityMag = agent.velocity.magnitude;
            float speedNormalized = Mathf.Clamp01(velocityMag / (agent.speed > 0 ? agent.speed : 1f));

            float turnSpeed = Mathf.Lerp(minTurnSpeed, maxTurnSpeed, speedNormalized);
            turnSpeed = Mathf.Min(turnSpeed, 5f); 

            Quaternion want = Quaternion.LookRotation(forwardSource.normalized, Vector3.up);
            transform.rotation = Quaternion.Slerp(transform.rotation, want, Time.deltaTime * turnSpeed);
        }
    }
    public void AlertToSound(Vector3 sourcePos)
    {

        worldState["LastHeardPlayerPos"] = sourcePos;
        worldState["HasHeardPlayer"] = true;
        worldState["Investigating"] = true;

        currentPlan = null;
        currentAction = null;
        planIndex = 0;

        if (verboseLogs)
            Debug.Log($"{name} AlertToSound: heard sound at {sourcePos}");
    }

}

