[CreateAssetMenu(menuName = "GOAP/FindFood")]
public class FindFoodAction : GOAPAction
{
    public float searchRadius = 20f;
    public LayerMask foodMask;
    public float searchInterval = 0.5f;

    Transform found;
    float timer;

    private void OnEnable()
    {
        actionName = "FindFood";
        preconditions = new List<string>(); // always available
        effects = new List<string>
        {
            GOAPKeys.HasFoodTarget,
            GOAPKeys.KnownFood,
            GOAPKeys.FoodTarget
        };
    }
    public override void OnDrawGizmosSelected()
    {
        if (agent != null)
        {
            Gizmos.color = Color.blue;
            Gizmos.DrawWireSphere(agent.transform.position, searchRadius);
        }

        if (found != null)
        {
            Gizmos.color = Color.green;
            Gizmos.DrawSphere(found.position, 0.2f);
        }
    }

    public override bool CheckPreconditions(Dictionary<string, object> worldState) => true;

    public override bool StartAction(Dictionary<string, object> worldState)
    {
        InRange = false;
        timer = 0f;
        found = null;

        // If planner already seeded a KnownFood, consume it immediately
        if (worldState.TryGetValue(GOAPKeys.KnownFood, out var k) && k is Transform t)
        {
            found = t;
            worldState[GOAPKeys.HasFoodTarget] = true;
            worldState[GOAPKeys.FoodTarget] = found;
            SetTarget(found); // so rotation can face it
            return true;
        }

        return true; // action can still run to search
    }

    public override bool PerformAction(float deltaTime, Dictionary<string, object> worldState)
    {
        // If we already found something, mark it and finish
        if (found != null)
        {
            worldState[GOAPKeys.HasFoodTarget] = true;
            worldState[GOAPKeys.FoodTarget] = found;
            return true;
        }

        // Otherwise, periodically scan
        timer -= deltaTime;
        if (timer <= 0f)
        {
            timer = searchInterval;
            Collider[] hits = Physics.OverlapSphere(agent.transform.position, searchRadius, foodMask);
            if (hits.Length > 0)
            {
                float best = float.MaxValue;
                Transform bestT = null;
                foreach (var h in hits)
                {
                    float d = (h.transform.position - agent.transform.position).sqrMagnitude;
                    if (d < best)
                    {
                        best = d;
                        bestT = h.transform;
                    }
                }

                if (bestT != null)
                {
                    found = bestT;
                    worldState[GOAPKeys.HasFoodTarget] = true;
                    worldState[GOAPKeys.KnownFood] = found;
                    worldState[GOAPKeys.FoodTarget] = found;
                    SetTarget(found);
                    return true; // finished once food is identified
                }
            }
        }

        return false; // keep searching
    }

    public override bool RequiresInRange() => false;
}

using System.Collections.Generic;
using UnityEngine;

public abstract class GOAPAction : ScriptableObject
{
    public string actionName = "Action";
    public float cost = 1f;
    public float duration = 0.5f;

    [HideInInspector] public List<string> preconditions = new List<string>();
    [HideInInspector] public List<string> effects = new List<string>();

    public bool InRange { get; protected set; }
    public GameObject agent { get; private set; }
    public Transform target { get; protected set; }

    public void AwakeAction(GameObject agentGo)
    {
        agent = agentGo;
        ResetAction();
    }

    public void ResetAction()
    {
        InRange = false;
        target = null;
    }

    public abstract bool CheckPreconditions(Dictionary<string, object> worldState);
    public abstract bool StartAction(Dictionary<string, object> worldState);
    public abstract bool PerformAction(float deltaTime, Dictionary<string, object> worldState);

    public virtual bool RequiresInRange() => false;
    public virtual void SetTarget(Transform t) { target = t; }

    // NEW: optional gizmo drawing
    public virtual void OnDrawGizmosSelected() { }
}

public static class GOAPKeys
{
    public const string Fed = "Fed";
    public const string HasFoodTarget = "HasFoodTarget";
    public const string AtFood = "AtFood";
    public const string FoodTarget = "FoodTarget"; // stores Transform
    public const string KnownFood = "KnownFood";
    public const string HasHeardPlayer = "HasHeardPlayer";
    public const string LastHeardPlayerPos = "LastHeardPlayerPos"; // Vector3
    public const string Investigating = "Investigating";
}

