using System.Collections.Generic;
using System.Linq;
// Simple greedy planner: picks the first action sequence that satisfies the goal using DFS up to a depth.
// Not a full A* GOAP, but lightweight and deterministic for small action sets.
public static class GOAPPlanner
{
    public static List<GOAPAction> Plan(GameObject agent, List<GOAPAction> availableActions, Dictionary<string, object> worldState, List<string> goalEffects, int maxDepth = 5)
    {
        // Ensure actions are reset
        foreach (var a in availableActions) a.ResetAction();

        var usable = availableActions.Where(a => a.CheckPreconditions(worldState)).ToList();

        var plan = new List<GOAPAction>();
        var visited = new HashSet<string>();

        bool DFS(Dictionary<string, object> state, List<GOAPAction> currentPlan, int depth)
        {
            if (depth > maxDepth) return false;

            // If all goal effects present in state, success
            bool goalMet = true;
            foreach (var g in goalEffects)
            {
                if (!state.ContainsKey(g) || !(state[g] as bool? == true))
                {
                    goalMet = false;
                    break;
                }
            }
            if (goalMet)
            {
                plan = new List<GOAPAction>(currentPlan);
                return true;
            }

            // Try each usable action that isn't already used
            foreach (var action in usable)
            {
                if (currentPlan.Contains(action)) continue;

                // Additional precondition check at this state
                if (!action.CheckPreconditions(state)) continue;

                // simulate applying action effects to a new state copy
                var newState = new Dictionary<string, object>(state);
                foreach (var eff in action.effects)
                    newState[eff] = true;

                currentPlan.Add(action);
                if (DFS(newState, currentPlan, depth + 1)) return true;
                currentPlan.RemoveAt(currentPlan.Count - 1);
            }

            return false;
        }

        var startPlan = new List<GOAPAction>();
        if (DFS(new Dictionary<string, object>(worldState), startPlan, 0))
        {
            // prepare actions
            foreach (var a in plan) a.AwakeAction(agent);
            return plan;
        }

        return null;
    }
}

