[CreateAssetMenu(menuName = "GOAP/Investigate")]
public class InvestigateAction : GOAPAction
{
    public float acceptableRange = 1.5f;
    NavMeshAgent nav;
    Vector3 investigatePos;

    private void OnEnable()
    {
        actionName = "Investigate";
        preconditions = new List<string> { "HasHeardPlayer" };
        effects = new List<string> { "InvestigatingComplete" };
    }

    public override bool CheckPreconditions(Dictionary<string, object> worldState)
    {
        return worldState.TryGetValue("HasHeardPlayer", out var o) && o is bool b && b;
    }

    public override bool StartAction(Dictionary<string, object> worldState)
    {
        if (!worldState.TryGetValue("LastHeardPlayerPos", out var o) || !(o is Vector3 pos))
            return false;

        investigatePos = pos;
        nav = agent.GetComponent<NavMeshAgent>();
        if (nav == null || !nav.isOnNavMesh) return false;

        nav.isStopped = false;
        nav.SetDestination(investigatePos);
        return true;
    }

    public override bool PerformAction(float deltaTime, Dictionary<string, object> worldState)
    {
        if (nav == null) return true;

        if (!nav.pathPending && nav.remainingDistance <= acceptableRange)
        {
            worldState["Investigating"] = false;
            worldState["HasHeardPlayer"] = false;
            return true; // finished
        }
        return false;
    }
}

