[CreateAssetMenu(menuName = "GOAP/MoveTo")]
public class MoveToAction : GOAPAction
{
    public float acceptableRange = 1.2f;
    NavMeshAgent nav;
    Transform destination;

    private void OnEnable()
    {
        actionName = "MoveTo";
        preconditions = new List<string> { GOAPKeys.HasFoodTarget };
        effects = new List<string> { GOAPKeys.AtFood };
    }
    public override void OnDrawGizmosSelected()
    {
        if (target != null)
        {
            Gizmos.color = Color.green;
            Gizmos.DrawSphere(target.position, 0.2f);
            Gizmos.DrawLine(agent.transform.position, target.position);
        }

        if (agent != null)
        {
            Gizmos.color = Color.magenta;
            Gizmos.DrawWireSphere(agent.transform.position, acceptableRange);
        }
    }

    public override bool CheckPreconditions(Dictionary<string, object> worldState)
    {
        return worldState.TryGetValue(GOAPKeys.HasFoodTarget, out var o) && o is bool b && b
            && worldState.TryGetValue(GOAPKeys.FoodTarget, out var t) && t is Transform;
    }

    public override bool StartAction(Dictionary<string, object> worldState)
    {
        if (!worldState.TryGetValue(GOAPKeys.FoodTarget, out var o) || !(o is Transform t))
            return false;

        destination = t;
        nav = agent.GetComponent<NavMeshAgent>();
        if (nav == null || !nav.isOnNavMesh) return false;

        nav.isStopped = false;
        nav.SetDestination(destination.position);
        SetTarget(destination); // so rotation knows who to face
        return true;
    }

    public override bool PerformAction(float deltaTime, Dictionary<string, object> worldState)
    {
        if (destination == null) return true;
        if (nav == null) nav = agent.GetComponent<NavMeshAgent>();

        if (!nav.pathPending && nav.remainingDistance <= acceptableRange)
        {
            worldState[GOAPKeys.AtFood] = true;
            return true; // finished
        }

        // keep destination updated if target moves
        if (destination != null && nav.hasPath)
        {
            if (Vector3.Distance(nav.destination, destination.position) > 0.5f)
                nav.SetDestination(destination.position);
        }

        return false;
    }

    public override bool RequiresInRange() => true;
}

