[CreateAssetMenu(menuName = "GOAP/Wander")]
public class WanderAction : GOAPAction
{
    public float radius = 6f;
    public float interval = 3f;
    public float arrivalThreshold = 0.6f;
    public float idleMin = 1f;
    public float idleMax = 3f;
    public int sampleRetries = 6;

    NavMeshAgent nav;
    Vector3 currentDestination;
    bool hasDestination;
    float idleUntil;
    float nextPickTime;

    private void OnEnable()
    {
        actionName = "Wander";
        preconditions = new List<string>(); // always available
        effects = new List<string> { "Wandering" };
    }
    public override void OnDrawGizmosSelected()
    {
        if(agent == null)
        {
            Debug.Log("Agent is null...");
            return;
        }
        if (agent != null)
        {
            Gizmos.color = Color.cyan;
            Gizmos.DrawWireSphere(agent.transform.position, radius);

            if (hasDestination)
            {
                Gizmos.color = Color.yellow;
                Gizmos.DrawSphere(currentDestination, 0.15f);
                Gizmos.DrawLine(agent.transform.position, currentDestination);
            }
        }
    }

    public override bool CheckPreconditions(Dictionary<string, object> worldState) => true;

    public override bool StartAction(Dictionary<string, object> worldState)
    {
        nav = agent.GetComponent<NavMeshAgent>();
        hasDestination = false;
        idleUntil = 0f;
        nextPickTime = Time.time + Random.Range(0f, interval);
        return true;
    }

    public override bool PerformAction(float deltaTime, Dictionary<string, object> worldState)
    {
        if (nav == null || !nav.isOnNavMesh) return false;

        // If arrived, idle
        if (hasDestination && !nav.pathPending && nav.remainingDistance <= arrivalThreshold)
        {
            if (idleUntil == 0f)
            {
                idleUntil = Time.time + Random.Range(idleMin, idleMax);
                nav.isStopped = true;
            }

            if (Time.time < idleUntil)
                return false; // still idling

            // finished idling, reset
            hasDestination = false;
            idleUntil = 0f;
            nextPickTime = Time.time + Random.Range(0.2f * interval, 1.5f * interval);
        }

        // If no destination, pick one
        if (!hasDestination && Time.time >= nextPickTime)
        {
            for (int i = 0; i < sampleRetries; i++)
            {
                Vector3 candidate = agent.transform.position + Random.insideUnitSphere * radius;
                candidate.y = agent.transform.position.y;
                if (NavMesh.SamplePosition(candidate, out NavMeshHit hit, 2f, NavMesh.AllAreas))
                {
                    currentDestination = hit.position;
                    hasDestination = true;
                    nav.isStopped = false;
                    nav.SetDestination(currentDestination);

                    worldState["WanderDestination"] = currentDestination;
                    worldState["Wandering"] = true;
                    break;
                }
            }
        }

        return false; // never completes on its own
    }

    public override bool RequiresInRange() => false;
}

using UnityEngine;
using System.Collections;

public class WaveSpawner : MonoBehaviour
{
    [System.Serializable]
    public class Wave
    {
        public int count;
        public float interval;
    }

    public Wave[] waves;
    public Transform[] spawnPoints;

    private int currentWave = 0;

    public void StartNight()
    {
        StartCoroutine(SpawnWave(waves[currentWave]));
    }

    private IEnumerator SpawnWave(Wave wave)
    {
        for (int i = 0; i < wave.count; i++)
        {
            SpawnZombie();
            yield return new WaitForSeconds(wave.interval);
        }
        currentWave++;
    }

    private void SpawnZombie()
    {
        Transform point = spawnPoints[Random.Range(0, spawnPoints.Length)];
        GameManager.Instance.SpawnEnemy(point.position, point.rotation);
    }
}

using UnityEngine;
using UnityEngine.AI;
using System.Collections.Generic;

public class AmbientSpawner : MonoBehaviour
{
    public SpawnVolumeType volumeType;
    public float spawnRadius = 10f;
    public Vector3 spawnExtents = new Vector3(5, 5, 5);
    public LayerMask obstructionMask;
    public int maxSpawnTries = 5;
    public float clearanceRadius = 0.5f;

    Queue<GameObject> retryQueue = new Queue<GameObject>();

    public void Spawn(GameObject prefab)
    {
        Vector3 pos;
        if (TryFindValidSpawnPoint(out pos))
        {
            Instantiate(prefab, pos, Quaternion.identity);
        }
        else
        {
            retryQueue.Enqueue(prefab);
        }
    }

    bool TryFindValidSpawnPoint(out Vector3 result)
    {
        for (int i = 0; i < maxSpawnTries; i++)
        {
            Vector3 candidate = RandomPointInVolume();
            candidate += Vector3.up * 2f; 

            if (Physics.SphereCast(candidate, clearanceRadius, Vector3.down, out RaycastHit hit, 10f, ~0, QueryTriggerInteraction.Ignore))
            {
                Vector3 groundPos = hit.point;

                if (!Physics.CheckSphere(groundPos, clearanceRadius, obstructionMask))
                {
                    if (NavMesh.SamplePosition(groundPos, out NavMeshHit navHit, 1.0f, NavMesh.AllAreas))
                    {
                        result = navHit.position;
                        return true;
                    }
                }
            }
        }

        result = Vector3.zero;
        return false;
    }

    Vector3 RandomPointInVolume()
    {
        if (volumeType == SpawnVolumeType.Sphere)
        {
            return transform.position + Random.insideUnitSphere * spawnRadius;
        }
        else 
        {
            return transform.position + new Vector3(
                Random.Range(-spawnExtents.x, spawnExtents.x),
                Random.Range(-spawnExtents.y, spawnExtents.y),
                Random.Range(-spawnExtents.z, spawnExtents.z)
            );
        }
    }

    void Update()
    {
        if (retryQueue.Count > 0)
        {
            GameObject prefab = retryQueue.Dequeue();
            Spawn(prefab);
        }
    }
}

using System.Collections.Generic;
using Unity.VisualScripting;
using UnityEngine;

public enum DoorLockType  
{
    None, // no lock on this door, can just be opened or closed.

    Key_Lock,

}

public class DoorHandle : IInteractable
{
    [SerializeField] Animator doorAnim;

    [SerializeField] DoorLockType lockType;

    public float animationTime = 1.0f;


    private void Start()
    {
        OnInteract += () =>
        {
            bool isValidInteraction = true;

            switch (lockType)
            {
                case DoorLockType.Key_Lock:
                    {
                        if (!PlayerHasKey())
                        {
                            isValidInteraction = false;                
                        }
                    }
